var n=`0872-halwa-puri`;var t=`world-0872`;var a=`PK`;var o=`south-asia`;var s=8;var r=72;var l={en:`Halwa Puri`,ua:`Халва пурі`};var g={en:`Halwa Puri is a Pakistan dish made with whole wheat flour, semolina flour, almond. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Халва пурі, страва кухні країни Пакистан. Основні складники: цільнозернове пшеничне борошно, семоліна, мигдаль. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`whole-wheat-flour`,320,`g`],[`water`,180,`ml`],[`table-salt`,5,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 18 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 18 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:18,i:[[`canola-oil`,650,`ml`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 17 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 17 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:17,i:[[`semolina-flour`,260,`g`],[`ghee`,85,`g`],[`water`,490,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`white-granulated-sugar`,155,`g`],[`ground-cardamom`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`almond`,35,`g`]]}];var u={slug:n,id:t,country:`PK`,region:o,servings:8,minutes:72,title:l,text:g,steps:d};export{a as country,u as default,t as id,r as minutes,o as region,s as servings,n as slug,d as steps,g as text,l as title};